def experiment(inputs):
    import random
    def run(seed, steps=200):
        random.seed(seed)
        weights = [0.5] * 5
        for _ in range(steps):
            noise = [random.random() for _ in range(5)]
            weights = [(w + n)/2 for w, n in zip(weights, noise)]
        return weights
    wA = run(inputs['seedA'])
    wB = run(inputs['seedB'])
    variance = sum((a-b)**2 for a, b in zip(wA, wB)) / len(wA)
    return {'preference_variance': variance}

